const list = $input.all().map((i) => i.json);
const today = new Date().toLocaleDateString('es-CO', { timeZone: 'America/Bogota', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const overdue = list.filter(f => f.due_date && new Date(f.due_date) < new Date());
const dueToday = list.filter(f => {
  if (!f.due_date) return false;
  const d = new Date(f.due_date);
  const now = new Date();
  return d.toDateString() === now.toDateString();
});
const upcoming = list.filter(f => {
  if (!f.due_date) return true;
  const d = new Date(f.due_date);
  const now = new Date();
  return d > now && d.toDateString() !== now.toDateString();
});

const formatRow = (f) => {
  const due = f.due_date ? new Date(f.due_date).toLocaleDateString('es-CO', { timeZone: 'America/Bogota' }) : 'sin fecha';
  return `• [${f.type || 'general'}] ${f.notes || 'sin nota'} — vence: ${due} (${f.contact_type || 'contacto'}: ${f.contact_id || 'N/A'})`;
};

const sections = [];
if (overdue.length > 0) sections.push(`**VENCIDOS (${overdue.length}):**\n${overdue.map(formatRow).join('\n')}`);
if (dueToday.length > 0) sections.push(`**HOY (${dueToday.length}):**\n${dueToday.map(formatRow).join('\n')}`);
if (upcoming.length > 0) sections.push(`**PRÓXIMOS (${upcoming.length}):**\n${upcoming.map(formatRow).join('\n')}`);

const digestText = sections.join('\n\n') || 'Sin detalles disponibles.';

return [{
  json: {
    total: list.length,
    overdue_count: overdue.length,
    today_count: dueToday.length,
    upcoming_count: upcoming.length,
    digest_text: digestText,
    date_label: today,
    discord_message: {
      embeds: [{
        title: `📋 Resumen diario de seguimientos — Peskids`,
        color: overdue.length > 0 ? 15158332 : 3447003,
        description: digestText.length > 3900 ? digestText.substring(0, 3900) + '\n...' : digestText,
        fields: [
          { name: 'Total pendientes', value: String(list.length), inline: true },
          { name: 'Vencidos', value: String(overdue.length), inline: true },
          { name: 'Vencen hoy', value: String(dueToday.length), inline: true }
        ],
        footer: { text: today }
      }]
    }
  }
}];
